sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    var deptObj = api.data.look_up_departments.results;
    var len = deptObj.length;

    var deptArr = [];

    for (var i = 0; i < len; i++) {
        var dept = {id: deptObj[i].row_data.uniqueValue,
        label: deptObj[i].row_data.displayValue
        };
        deptArr.push(dept);
    }
    return JSON.stringify(deptArr);
}
